STYLES = {'S0': '\n:root {\n  --bg: #f3f4f6;\n  --card: #ffffff;\n  --text: #111827;\n  --muted: #6b7280;\n  --header: #9ca3af;\n  --sep: #eef0f3;\n  --track: #e8eaed;\n  --row-alt: #f8f9fb;\n  --watermark: #d1d5db;\n  --blue: #2563eb;\n  --blue-hatch: #93c5fd;\n  --ok: #059669;\n  --ok-bg: #ecfdf5;\n  --bad: #dc2626;\n  --bad-bg: #fef2f2;\n  --partial: #d97706;\n  --partial-bg: #fffbeb;\n  --fail: #9ca3af;\n  --fail-bg: #f3f4f6;\n  --pos: #059669;\n  --neg: #dc2626;\n}\n\n* { box-sizing: border-box; margin: 0; padding: 0; }\n\nhtml, body {\n  background: var(--bg);\n  color: var(--text);\n  font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n\nbody {\n  display: flex;\n  justify-content: center;\n  align-items: flex-start;\n  padding: 40px 24px 48px;\n  min-height: 100vh;\n}\n\n.page { width: 1160px; max-width: 100%; }\n\n.card {\n  background: var(--card);\n  border-radius: 20px;\n  padding: 32px 36px 28px;\n  box-shadow:\n    0 1px 2px rgba(16, 24, 40, 0.03),\n    0 10px 28px rgba(16, 24, 40, 0.07);\n  border: 1px solid rgba(16, 24, 40, 0.04);\n}\n\n.header { margin-bottom: 18px; }\n\n.title {\n  font-size: 22px;\n  font-weight: 700;\n  letter-spacing: -0.02em;\n  color: var(--text);\n  line-height: 1.25;\n}\n\n.subtitle {\n  margin-top: 6px;\n  font-size: 13px;\n  font-weight: 400;\n  color: var(--muted);\n  letter-spacing: 0.01em;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 10px;\n}\n.brand-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  height: 16px;\n  padding: 0;\n  background: none;\n  border: none;\n  border-radius: 0;\n  color: #374151;\n  font-size: 13px;\n  font-weight: 600;\n  line-height: 16px;\n}\n.brand-chip .brand-icon {\n  width: 14px;\n  height: 14px;\n  display: block;\n  flex-shrink: 0;\n  transform: none;\n}\n.brand-chip img.brand-icon { object-fit: contain; border-radius: 3px; }\n.brand-chip .brand-label {\n  display: block;\n  padding: 0;\n  line-height: 16px;\n}\n.brand-sep { color: #d1d5db; font-weight: 400; }\n.brand-rest { color: var(--muted); font-weight: 400; font-size: 13px; }\n\n\n.legend {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 16px 20px;\n  margin-top: 14px;\n  margin-bottom: 4px;\n}\n\n.legend-item {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 12px;\n  color: var(--muted);\n  font-weight: 500;\n}\n\n.swatch {\n  width: 22px;\n  height: 10px;\n  border-radius: 999px;\n  flex-shrink: 0;\n}\n.swatch.solid { background: var(--blue); }\n.swatch.hatch {\n  background: repeating-linear-gradient(\n    -45deg, var(--blue-hatch), var(--blue-hatch) 2px, var(--blue) 2px, var(--blue) 3.5px\n  );\n  border: 1px solid rgba(37, 99, 235, 0.35);\n}\n\n.watermark {\n  margin-top: 18px;\n  text-align: center;\n  font-size: 11px;\n  font-style: italic;\n  color: var(--watermark);\n}\n\n.note {\n  margin-top: 10px;\n  font-size: 11.5px;\n  color: var(--muted);\n  line-height: 1.45;\n}\n\n.skill-cell { display: flex; align-items: center; gap: 10px; min-width: 0; }\n.dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; }\n.skill-name { font-size: 14px; font-weight: 500; color: var(--text); }\n.skill-name.baseline { color: var(--muted); font-weight: 400; }\n', 'S1': '\n.table { width: 100%; border-collapse: separate; border-spacing: 0; table-layout: fixed; }\n.table thead th {\n  font-size: 11px; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase;\n  color: var(--header); padding: 10px 8px 12px; border-bottom: 1px solid var(--sep); white-space: nowrap;\n}\n.table thead th.col-skill { text-align: left; width: 18%; padding-left: 12px; }\n.table thead th.col-bar { text-align: left; width: 42%; }\n.table thead th.col-metric { text-align: center; width: 10%; }\n.table tbody tr { background: #fff; }\n.table tbody tr:nth-child(even) { background: var(--row-alt); }\n.table tbody tr + tr td { border-top: 1px solid var(--sep); }\n.table tbody td { padding: 14px 8px; vertical-align: middle; }\n.table tbody td.col-skill { padding-left: 12px; }\n.bar-wrap { display: flex; align-items: center; gap: 10px; width: 100%; }\n.track {\n  position: relative; flex: 1 1 auto; height: 20px; background: var(--track);\n  border-radius: 999px; overflow: visible;\n}\n.bar-solid {\n  position: absolute; left: 0; top: 0; height: 100%; border-radius: 999px 0 0 999px;\n  display: flex; align-items: center; justify-content: center; z-index: 2;\n}\n.bar-solid.round-full { border-radius: 999px; }\n.bar-hatch { position: absolute; top: 0; height: 100%; z-index: 1; border-radius: 0 999px 999px 0; }\n.pct-in { position: relative; z-index: 3; font-size: 11px; font-weight: 700; color: #fff; }\n.pct-tip { flex: 0 0 auto; min-width: 48px; font-size: 13px; font-weight: 700; font-variant-numeric: tabular-nums; }\n.metric { text-align: center; font-size: 13.5px; font-variant-numeric: tabular-nums; font-weight: 400; }\n.metric.empty { color: var(--muted); }\n.metric.best { font-weight: 700; }\n.axis-row td { padding: 6px 8px 0 !important; border-top: none !important; background: transparent !important; }\n.axis { position: relative; height: 22px; margin-right: 58px; }\n.axis-line { position: absolute; left: 0; right: 0; top: 2px; height: 1px; background: #e5e7eb; }\n.axis-tick { position: absolute; top: 0; transform: translateX(-50%); text-align: center; }\n.axis-tick::before { content: ""; display: block; width: 1px; height: 6px; background: #9ca3af; margin: 0 auto 4px; }\n.axis-tick span { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; }\n', 'S2': '\n.task-meta {\n  margin-top: 10px;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px 16px;\n  align-items: baseline;\n}\n.task-id {\n  font-size: 13px;\n  font-weight: 700;\n  color: var(--blue);\n  background: #eff6ff;\n  padding: 3px 10px;\n  border-radius: 999px;\n  letter-spacing: 0.02em;\n}\n.task-repo {\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--text);\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n}\n.task-desc {\n  margin-top: 6px;\n  font-size: 12.5px;\n  color: var(--muted);\n  line-height: 1.45;\n  max-width: 920px;\n}\n\n.table {\n  width: 100%;\n  border-collapse: separate;\n  border-spacing: 0;\n  table-layout: fixed;\n  margin-top: 8px;\n}\n.table thead th {\n  font-size: 10.5px;\n  font-weight: 600;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--header);\n  padding: 10px 6px 12px;\n  border-bottom: 1px solid var(--sep);\n  white-space: nowrap;\n  text-align: center;\n}\n.table thead th.col-skill { text-align: left; width: 18%; padding-left: 12px; }\n.table thead th.col-run { width: 8%; }\n.table thead th.col-pass2 { width: 8%; }\n.table thead th.col-metric { width: 9%; }\n.table thead th.col-vs { width: 12%; }\n\n.table tbody tr { background: #fff; }\n.table tbody tr:nth-child(even) { background: var(--row-alt); }\n.table tbody tr + tr td { border-top: 1px solid var(--sep); }\n.table tbody td {\n  padding: 12px 6px;\n  vertical-align: middle;\n  text-align: center;\n  font-variant-numeric: tabular-nums;\n}\n.table tbody td.col-skill { text-align: left; padding-left: 12px; }\n\n.pill {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 42px;\n  height: 26px;\n  padding: 0 10px;\n  border-radius: 999px;\n  font-size: 12px;\n  font-weight: 700;\n}\n.pill.pass { background: var(--ok-bg); color: var(--ok); }\n.pill.fail { background: var(--bad-bg); color: var(--bad); }\n.pill.dash { background: var(--fail-bg); color: var(--fail); }\n\n.metric { font-size: 13px; color: var(--text); font-weight: 500; }\n.metric.empty { color: var(--muted); font-weight: 400; }\n.metric.best { font-weight: 700; }\n\n.vs-cell { display: flex; flex-direction: column; align-items: center; gap: 2px; }\n.vs-delta { font-size: 13px; font-weight: 600; }\n.vs-delta.pos { color: var(--pos); }\n.vs-delta.neg { color: var(--neg); }\n.vs-delta.zero { color: var(--muted); }\n.vs-delta.base { color: var(--muted); font-weight: 500; }\n', 'S3': '\n.matrix-scroll { width: 100%; overflow-x: auto; border: 1px solid var(--sep); border-radius: 12px; }\n.matrix { width: 100%; border-collapse: separate; border-spacing: 0; min-width: 980px; }\n.matrix thead th {\n  font-size: 10px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase;\n  color: var(--header); padding: 10px 4px; border-bottom: 1px solid var(--sep); background: #fff;\n}\n.matrix thead th.sticky-col {\n  text-align: left; padding-left: 14px; min-width: 150px; position: sticky; left: 0; z-index: 3; background: #fff;\n}\n.matrix thead th.task-col { text-align: center; min-width: 28px; width: 28px; font-size: 9px; color: #b0b5bd; }\n.matrix thead th.summary { text-align: center; min-width: 72px; border-left: 1px solid var(--sep); }\n.matrix tbody tr { background: #fff; }\n.matrix tbody tr:nth-child(even) { background: var(--row-alt); }\n.matrix tbody tr:nth-child(even) td.sticky-col { background: var(--row-alt); }\n.matrix tbody tr + tr td { border-top: 1px solid var(--sep); }\n.matrix tbody td { padding: 8px 3px; vertical-align: middle; text-align: center; }\n.matrix tbody td.sticky-col {\n  text-align: left; padding: 10px 14px; position: sticky; left: 0; z-index: 1; background: #fff;\n  border-right: 1px solid var(--sep);\n}\n.matrix tbody td.summary {\n  border-left: 1px solid var(--sep); font-size: 12px; font-weight: 600; white-space: nowrap;\n}\n.cell-mark { display: inline-flex; flex-direction: column; align-items: center; min-height: 28px; justify-content: center; }\n.cell-mark .runs { display: inline-flex; gap: 2px; font-size: 11px; font-weight: 700; }\n.cell-mark .runs .y { color: var(--ok); }\n.cell-mark .runs .n { color: #d1d5db; }\n.summary-sub { display: block; font-size: 10px; font-weight: 500; color: var(--muted); margin-top: 2px; }\n.chip {\n  display: inline-flex; align-items: center; justify-content: center; min-width: 28px; height: 18px;\n  padding: 0 6px; border-radius: 6px; font-size: 10px; font-weight: 700;\n}\n.chip.both { background: #ecfdf5; color: #059669; }\n.chip.one { background: #fffbeb; color: #d97706; }\n.chip.none { background: #f3f4f6; color: #9ca3af; }\n'}
